{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "(+)-Bicuculline, a structurally related phthalideisoquinoline alkaloid, penetrated rat brain in a dose-dependent manner measured by LC-MS/MS, providing direct in vivo evidence of CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "α-Allocryptopine was detected in rat CSF after administration, directly indicating passage across the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tetrahydroberberine was detected in rat CSF, demonstrating that this related alkaloid can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Schisandrin B showed a relatively high brain/plasma equilibration rate with logPSFu,brain of -3.2, supporting meaningful BBB permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Schisandrin B reached detectable and substantial mouse brain tissue concentrations as early as 15 minutes and up to 0.327 µg/g at 2 hours, confirming in vivo CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Isocorydine effectively crossed the BBB in rats, with considerable brain levels detected within 10 minutes of administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple structurally related alkaloids show consistent direct in vivo brain, CSF, or tissue evidence of BBB penetration, and the physicochemical prior is favorable for passive CNS access. The weight of experimental evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental measurement for the query molecule itself.",
    "No explicit P-gp or other efflux transporter data for the query molecule.",
    "Some records are qualitative CSF/tissue detection rather than quantitative unbound brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

